<?php require_once __DIR__.'/../../app/layout.php'; $a=require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM activities WHERE id=?')->execute([$id]);audit($pdo,$a['id'],'activity_deleted','activity',$id);flash('Activity deleted.');}else{$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');if($title===''||$description===''){flash('Title and description are required.','error');}elseif($id){$pdo->prepare('UPDATE activities SET title=?,activity_date=?,location=?,description=?,status=?,featured=? WHERE id=?')->execute([$title,$_POST['activity_date']??date('Y-m-d'),trim($_POST['location']??'')?:null,$description,$_POST['status']??'active',isset($_POST['featured'])?1:0,$id]);audit($pdo,$a['id'],'activity_updated','activity',$id);flash('Activity updated.');}else{$pdo->prepare('INSERT INTO activities (title,activity_date,location,description,status,featured) VALUES (?,?,?,?,?,?)')->execute([$title,$_POST['activity_date']??date('Y-m-d'),trim($_POST['location']??'')?:null,$description,$_POST['status']??'active',isset($_POST['featured'])?1:0]);$id=(int)$pdo->lastInsertId();audit($pdo,$a['id'],'activity_created','activity',$id);flash('Activity created.');}redirect('/admin/activities.php');}}
$edit=['id'=>'','title'=>'','activity_date'=>date('Y-m-d'),'location'=>'','description'=>'','status'=>'active','featured'=>0];if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM activities WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:$edit;}$rows=$pdo->query('SELECT * FROM activities ORDER BY activity_date DESC')->fetchAll();header_html('Manage activities');?><h1>Manage activities</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><label>Title<input name="title" value="<?=e($edit['title'])?>" required></label><label>Date<input type="date" name="activity_date" value="<?=e($edit['activity_date'])?>" required></label><label>Location<input name="location" value="<?=e((string)$edit['location'])?>"></label><label>Description<textarea name="description" required><?=e($edit['description'])?></textarea></label><label>Status<select name="status"><option value="active" <?=$edit['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$edit['status']==='inactive'?'selected':''?>>Inactive</option></select></label><label><input type="checkbox" name="featured" <?=$edit['featured']?'checked':''?>> Feature on home page</label><button><?= $edit['id']?'Update':'Create' ?> activity</button></form><h2>All activities</h2><table><tr><th>Title</th><th>Date</th><th>Location</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['activity_date'])?></td><td><?=e((string)$r['location'])?></td><td><?=e($r['status'])?></td><td><a href="?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table><?php footer_html();
